		offset += el.totalSize;
		el = readElement(tbs.value, offset);
		if (!el || el.tag !== ASN1_TAG_SEQUENCE) return null;
		offset += el.totalSize;
		el = readElement(tbs.value, offset);
		if (!el || el.tag !== ASN1_TAG_SEQUENCE) return null;
		offset += el.totalSize;
		el = readElement(tbs.value, offset);
		if (!el || el.tag !== ASN1_TAG_SEQUENCE) return null;
		offset += el.totalSize;
		el = readElement(tbs.value, offset);
		if (!el || el.tag !== ASN1_TAG_SEQUENCE) return null;
		offset += el.totalSize;
		return readElementRaw(tbs.value, offset);
